import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [symbol, setSymbol] = useState('BBCA.JK');
  const [stockData, setStockData] = useState([]);
  const [loading, setLoading] = useState(false);

    const fetchStock = async () => {
        setLoading(true);
        try {
            const res = await axios.get("http://localhost:5000/stock", {
                params: { symbol }
            });

            if (res.data && res.data.data) {
                setStockData(res.data.data);
            } else {
                alert('Invalid data received from server');
            }
        } catch (err) {
            console.error('Error details:', err);
            if (err.response) {
                if (err.response.status === 404) {
                    alert(`No data found for symbol: ${symbol}`);
                } else {
                    alert(`Server error: ${err.response.data?.error || 'Unknown error'}`);
                }
            } else if (err.request) {
                alert('Server not responding. Please check if backend is running.');
            } else {
                alert(`Failed to fetch data: ${err.message}`);
            }
        } finally {
            setLoading(false);
        }
    };

useEffect(() => {
  fetchStock();
}, []);

return (
    <div style={{ padding: '2rem' }}>
      <h1>Stock Data Viewer</h1>
      <input
          type="text"
          value={symbol}
          onChange={(e) => setSymbol(e.target.value)}
      />
      <button onClick={fetchStock}>Fetch Data</button>

      {loading ? (
          <p>Loading...</p>
      ) : (
          <table border="1" cellPadding="5" style={{ marginTop: '1rem' }}>
            <thead>
            <tr>
              <th>Datetime</th>
              <th>Open</th>
              <th>High</th>
              <th>Low</th>
              <th>Close</th>
              <th>Volume</th>
            </tr>
            </thead>
            <tbody>
            {stockData.map((row, i) => (
                <tr key={i}>
                  <td>{row.Datetime}</td>
                  <td>{row.Open}</td>
                  <td>{row.High}</td>
                  <td>{row.Low}</td>
                  <td>{row.Close}</td>
                  <td>{row.Volume}</td>
                </tr>
            ))}
            </tbody>
          </table>
      )}
    </div>
);
}

export default App;
